DO $reviewed_correction$ DECLARE n integer; BEGIN
SELECT count(*) INTO n FROM company_funding_rounds f JOIN companies c ON c.id=f.company_id WHERE c.slug='pni-sensor' AND f.round_key='xtechsearch-7-cash-prize-disclosure' AND f.closing_status='closed' AND f.note_en='Army names Protonex LLC dba PNI Sensor among ten cash-prize winners. USD450,000 is the shared winners pool, not this issuer allocation; no equal division inferred. Potential USD250,000 SBIR contract opportunity is not a received grant. Date held because Army text has inconsistent year references. Cash prize, not equity or debt.' AND f.amount IS NULL AND f.financing_type='undisclosed';
IF n<>1 THEN RAISE EXCEPTION 'PNI expected old prize fact mismatch'; END IF;
UPDATE company_funding_rounds f SET closing_status='announced',note_en='Army names Protonex LLC dba PNI Sensor among ten cash-prize winners. USD450,000 is the shared winners pool, not this issuer allocation; no equal division inferred. Potential USD250,000 SBIR contract opportunity is not a received grant. Date held because Army text has inconsistent year references. Cash prize, not equity or debt. Award announcement establishes a prize, not confirmed disbursement; payment date and amount remain unknown.',updated_at=now() FROM companies c WHERE c.id=f.company_id AND c.slug='pni-sensor' AND f.round_key='xtechsearch-7-cash-prize-disclosure' AND f.closing_status='closed' AND f.note_en='Army names Protonex LLC dba PNI Sensor among ten cash-prize winners. USD450,000 is the shared winners pool, not this issuer allocation; no equal division inferred. Potential USD250,000 SBIR contract opportunity is not a received grant. Date held because Army text has inconsistent year references. Cash prize, not equity or debt.';
GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'PNI correction row count mismatch'; END IF;
END $reviewed_correction$;
